/** Messages the main thread posts to the combined OB-Xf/Octopus AudioWorklet. */
export type MainToWorkletMsg =
    | { type: 'midi'; instance_id: number; status: number; d1: number; d2: number } // queued to pendingMidi, drained inside process()
    | { type: 'set_routing'; routing: number[] /* 17 */ } // per-channel instance bitmask: bit i of routing[ch] = instance i
    | { type: 'set_active'; instance_id: number; active: boolean } // power an instance on/off
    | { type: 'set_polyphony'; instance_id: number; voice_count: number } // no active callers; polyphony owned by legacy idx 3
    | { type: 'set_mpe'; instance_id: number; enabled: number } // per-instance MPE flag mirror (g_mpe_enabled)
    | { type: 'set_mod_wheel'; instance_id: number; value: number } // reserved CC 1 direct route
    | { type: 'set_sustain'; instance_id: number; enabled: number } // reserved CC 64 direct route
    | { type: 'set_mpe_glide_range'; instance_id: number; semitones: number } // MPE pitch-bend range in semitones
    | { type: 'set_matrix_row'; instance_id: number; row: number; src: string; tgt: string; depth: number } // MPE modulation matrix row set
    | { type: 'clear_matrix_row'; instance_id: number; row: number } // MPE modulation matrix row clear
    | { type: 'set_param'; instance_id: number; idx: number; value: number } // legacy-space 0..1 param write (queued)
    | { type: 'gain'; instance_id: number; value: number } // no active callers
    | { type: 'load_fxp'; instance_id: number; bytes: Uint8Array } // HEAVY; the ONLY message posted with a transfer list ([bytes.buffer])
    | { type: 'set_factory_patch'; instance_id: number; patch_id: number } // HEAVY (task-queued factory .fxp parse)
    | { type: 'panic'; instance_id: number } // all notes off for one instance
    | { type: 'panic_all' } // all notes off, every instance
    | { type: 'reset_patch'; instance_id: number } // reset one instance to the init patch
    | { type: 'get_param'; instance_id: number; idx: number } // request/reply — answered by param_value
    | { type: 'dump_all_params' } // bulk pull — answered by all_params_dumped
    | { type: 'restore_all_state'; synthParams: number[] /* 1080 */; drumParams: number[] | null /* 3456 */ } // staged engine-owned restore; drumParams null = synth-only
    | { type: 'dump_drum_params' } // bulk pull — answered by drum_params_dumped
    | { type: 'set_drum_layer_param'; instance_id: number; pad: number; layer: number; idx: number; value: number } // layer is the DENSE index (enabled+sampled layers packed from 0)
    | { type: 'get_drum_layer_param'; instance_id: number; pad: number; layer: number; idx: number } // DENSE layer index — answered by drum_layer_param_value
    | { type: 'get_patch_name'; instance_id: number } // no active callers — answered by patch_name
    | { type: 'ping' } // inline; 30 Hz liveness poll — answered by pong
    | { type: 'load_pcm'; instance_id: number; pad: number; layer: number; pcmL: Float32Array; frames: number } // HEAVY, no reply; layer is the DENSE index
    | { type: 'set_pcm_layer'; instance_id: number; pad: number; layer: number; gain: number; cutoff: number; res: number; mode: number; aA: number; aD: number; aS: number; aR: number; pan: number; pitch: number } // full-param layer push; layer is the DENSE index; pitch is the RATE multiplier 2^((knob-0.5)*2) ≈ 0.25..4, NOT 0..1
    | { type: 'set_pcm_note_map'; instance_id: number; note: number; pad: number } // map a MIDI note onto a pad
    | { type: 'set_pcm_layer_count'; instance_id: number; pad: number; count: number } // dense played-layer count for the pad
    | { type: 'set_pcm_choke'; instance_id: number; pad: number; group: number } // choke group for the pad
    | { type: 'clear_pcm'; instance_id: number } // HEAVY — frees the instance PCM bank
    | { type: 'fx_set_param'; instance_id: number; slot: number; param: number; value: number } // light queued setter; value in ENGINE units, NOT 0..1
    | { type: 'fx_set_enabled'; instance_id: number; slot: number; enabled: boolean } // INLINE — eager DSP activation at message-handler time
    | { type: 'fx_set_slot'; instance_id: number; slot: number; fx_id: number } // INLINE — eager DSP create at message-handler time; -1 = empty
    | { type: 'fx_move_slot'; instance_id: number; from: number; to: number } // INLINE — array-moves a slot whole content
    | { type: 'fx_get_out_param'; instance_id: number; slot: number; index: number } // inline direct reply — answered by fx_out_param
    | { type: 'fx_get_state' } // bulk pull — answered by fx_state
    | { type: 'fx_restore_state'; params: number[] /* 5280 */; slots: number[] /* 110 */; enabled: number[] /* 110 */ } // HEAVY; slots are fx ids -1..82, enabled is numeric 0/1
    | { type: 'mix_gain'; ch: number; gain: number } // linear gain for a mono engine channel
    | { type: 'mix_pan'; ch: number; pan: number } // -1..1 balance for a mono engine channel
    | { type: 'mix_mute'; ch: number; muted: boolean } // mute a mono engine channel
    | { type: 'mix_solo'; ch: number; soloed: boolean } // solo a mono engine channel
    | { type: 'mix_input_gain'; ch: number; gainDb: number } // input trim in dB
    | { type: 'mix_phase'; ch: number; inverted: boolean } // invert channel phase
    | { type: 'mix_pan_law'; ch: number; law: number } // pan law selector 0..3
    | { type: 'mix_name'; ch: number; name: string } // channel strip label
    | { type: 'mix_main_assign'; ch: number; on: boolean } // assign channel to the main bus
    | { type: 'mix_eq_gain'; ch: number; band: number; gainDb: number } // channel EQ band gain in dB
    | { type: 'mix_eq_freq'; ch: number; band: number; freqHz: number } // channel EQ band frequency in Hz
    | { type: 'mix_eq_q'; ch: number; band: number; q: number } // channel EQ band Q
    | { type: 'mix_eq_bypass'; ch: number; bypassed: boolean } // bypass the channel EQ
    | { type: 'mix_comp_enable'; ch: number; enabled: boolean } // enable the channel compressor
    | { type: 'mix_comp_param'; ch: number; param: number; value: number } // compressor param value (ENGINE units)
    | { type: 'mix_gate_enable'; ch: number; enabled: boolean } // enable the channel gate
    | { type: 'mix_gate_param'; ch: number; param: number; value: number } // gate param value (ENGINE units)
    | { type: 'mix_exp_enable'; ch: number; enabled: boolean } // enable the channel expander
    | { type: 'mix_exp_param'; ch: number; param: number; value: number } // expander param value (ENGINE units)
    | { type: 'mix_master_gain'; gain: number } // master bus gain
    | { type: 'mix_limiter_enabled'; enabled: boolean } // enable the master limiter
    | { type: 'mix_limiter_ceiling'; ceilingDb: number } // limiter ceiling in dB
    | { type: 'mix_limiter_release'; releaseMs: number } // limiter release in ms
    | { type: 'mix_clear_clip' } // clear the master clip indicator
    | { type: 'mix_get_params' } // devtools-only diagnostics, no in-repo sender — answered by mixer_params
    | { type: 'oct_key'; key: number; press: number } // INLINE; the SAVE key latches a HEAVY deferred save — answered by oct_state_saved
    | { type: 'oct_rotary'; idx: number; dir: number } // INLINE
    | { type: 'oct_transport'; running: number } // INLINE — run/stop the sequencer
    | { type: 'oct_pause' } // INLINE test hook (driven via window.__octopus)
    | { type: 'oct_tempo'; bpm: number } // INLINE — sets the engine BPM
    | { type: 'oct_zoom'; level: number } // INLINE test hook — sets the zoom level
    | { type: 'oct_midi_in'; status: number; d1: number; d2: number } // INLINE — no instance_id; feeds the firmware byte interpreters
    | { type: 'oct_shutdown' } // INLINE test hook — shuts the engine down
    | { type: 'oct_pump'; ms: number } // INLINE — RAF fallback while the context is suspended
    | { type: 'oct_save_state' } // HEAVY — answered by oct_state_bytes
    | { type: 'oct_load_state'; bytes: Uint8Array } // HEAVY — answered by oct_state_loaded; bytes are structured-cloned, NOT transferred
    | { type: 'oct_snapshot' } // INLINE test hook — answered by oct_snapshot

/** Replies and events the worklet posts back to the main thread. */
export type WorkletToMainMsg =
    | { type: 'ready' } // worklet boot finished
    | { type: 'constructed' } // no consumer — debug liveness
    | { type: 'error'; message: string; stack: string } // generic worklet error report
    | { type: 'oct_ready'; mirPtr: number; processedMirPtr: number; statusPtr: number } // hands over the MIR/status byte offsets; mirPtr posted but currently unread
    | { type: 'oct_state_saved'; bytes: Uint8Array | null } // internal GRID+PGM save bytes — posted by the task-queue save task
    | { type: 'oct_state_bytes'; bytes: Uint8Array | null } // explicit save dump bytes — reply to oct_save_state
    | { type: 'oct_state_loaded'; ok: boolean } // load ack — reply to oct_load_state
    | { type: 'oct_snapshot'; mir: number[] /* 170 */; runBit: number; tempo: number; zoom: number; tickCount: number } // one-shot MIR + transport snapshot — reply to the oct_snapshot request
    | { type: 'pong'; alive: boolean; ready: boolean; meters: number[] /* 10 */; voiceActivity: number[] /* 10 */; bufLPtr: number; bufRPtr: number } // liveness reply; alive/ready/bufLPtr/bufRPtr currently unread
    | { type: 'hw_midi'; packed: number[] } // packed firmware MIDI batches, posted per drained quantum
    | { type: 'fxp_loaded'; instance_id: number; success: boolean; rc: number; name: string } // load ack; rc currently unread
    | { type: 'param_value'; instance_id: number; idx: number; value: number } // reply to get_param
    | { type: 'patch_name'; instance_id: number; name: string } // reply to get_patch_name
    | { type: 'all_params_dumped'; params: number[] /* 1080 */ } // reply to dump_all_params
    | { type: 'all_state_restored' } // staged restore complete
    | { type: 'drum_params_dumped'; params: number[] /* 3456 */ } // reply to dump_drum_params
    | { type: 'drum_layer_param_value'; instance_id: number; pad: number; layer: number; idx: number; value: number } // reply to get_drum_layer_param (layer is the DENSE index)
    | { type: 'fx_out_param'; instance_id: number; slot: number; index: number; value: number } // inline direct reply to fx_get_out_param
    | { type: 'fx_state'; params: number[] /* 5280 */; slots: number[] /* 110 */; enabled: number[] /* 110 */ } // reply to fx_get_state
    | { type: 'fx_state_restored' } // ack for fx_restore_state
    | { type: 'fx_state_error'; message: string } // no listener — restoreFxState times out; kept in spec
    | { type: 'mixer_ready' } // CakeMix mixer engine booted
    | { type: 'mixer_error'; phase: string; message: string; stack?: string } // stack present on phase 'init' only — modeled optional
    | { type: 'mixer_meter'; peakL: number; peakR: number; rmsL: number; rmsR: number; clip: boolean; limiterGr: number; channelsJson: string } // master + per-channel metering (~every 10 blocks)
    | { type: 'mixer_params'; json: string } // diagnostics only — reply to mix_get_params
